arguments.content:
* {
    outline: none;
}

window#waybar {
    background-color: rgba(20, 20, 30, 0.7);
    color: #ffffff;
    font-family: "Fira Sans", sans-serif;
    font-size: 14px;
}

#workspaces {
    margin-left: 12px;
}

#workspaces button {
    padding: 0 12px;
    border-radius: 6px;
    color: #8888aa;
}

#workspaces button:hover {
    background-color: rgba(50, 50, 70, 0.9);
    color: #ffffff;
}

#workspaces button.focused {
    background-color: rgba(100, 120, 200, 0.6);
    color: #ffffff;
}

#window {
    margin-right: 12px;
    padding-left: 8px;
}

#clock {
    margin-right: 12px;
}

#battery {
    margin-right: 12px;
}

#tray {
    margin-right: 12px;
}

